INSERT INTO campus_societies (id, campus_id, name, category, description, initials) SELECT UUID(), 'ab2a761b-cb6b-11f1-a6f1-8c04ba146d31', 'Computer Science Society', 'Technical', 'Provides students with opportunities to explore computing developments through hackathons, coding contests, seminars and technical workshops.', 'CSS' FROM dual WHERE NOT EXISTS (SELECT 1 FROM campus_societies WHERE campus_id='ab2a761b-cb6b-11f1-a6f1-8c04ba146d31' AND name='Computer Science Society');
