INSERT INTO campus_societies (id, campus_id, name, category, description, initials) SELECT UUID(), 'ab2a761b-cb6b-11f1-a6f1-8c04ba146d31', 'Bazm-e-Adab', 'Literary', 'Encourages public speaking, declamation, Bait-Bazi, and Urdu literary appreciation through annual national championships.', 'BAZ' FROM dual WHERE NOT EXISTS (SELECT 1 FROM campus_societies WHERE campus_id='ab2a761b-cb6b-11f1-a6f1-8c04ba146d31' AND name='Bazm-e-Adab');
INSERT INTO campus_societies (id, campus_id, name, category, description, initials) SELECT UUID(), 'ab2a761b-cb6b-11f1-a6f1-8c04ba146d31', 'English Literary Society', 'Literary', 'Supports development of English debate, parliamentary declamation, and creative writing skills through competitions and campus publications.', 'ELS' FROM dual WHERE NOT EXISTS (SELECT 1 FROM campus_societies WHERE campus_id='ab2a761b-cb6b-11f1-a6f1-8c04ba146d31' AND name='English Literary Society');
INSERT INTO campus_societies (id, campus_id, name, category, description, initials) SELECT UUID(), 'ab2a761b-cb6b-11f1-a6f1-8c04ba146d31', 'Adventure Club', 'Sports', 'Organizes excursions, hiking, mountaineering trips, and environmental study visits across northern Pakistan and national parks.', 'ADV' FROM dual WHERE NOT EXISTS (SELECT 1 FROM campus_societies WHERE campus_id='ab2a761b-cb6b-11f1-a6f1-8c04ba146d31' AND name='Adventure Club');
INSERT INTO campus_societies (id, campus_id, name, category, description, initials) SELECT UUID(), 'ab2a761b-cb6b-11f1-a6f1-8c04ba146d31', 'Dramatics Club', 'Cultural', 'Organizes theatrical performances, short film screenings, scriptwriting workshops, and cultural festival productions throughout the year.', 'DC' FROM dual WHERE NOT EXISTS (SELECT 1 FROM campus_societies WHERE campus_id='ab2a761b-cb6b-11f1-a6f1-8c04ba146d31' AND name='Dramatics Club');
