INSERT INTO campus_societies (id, campus_id, name, category, description, initials) SELECT UUID(), 'ab2a8220-cb6b-11f1-a6f1-8c04ba146d31', 'Dramatics Club', 'Cultural', 'Organizes theatrical performances, short film screenings, scriptwriting workshops, and cultural festival productions throughout the year.', 'DC' FROM dual WHERE NOT EXISTS (SELECT 1 FROM campus_societies WHERE campus_id='ab2a8220-cb6b-11f1-a6f1-8c04ba146d31' AND name='Dramatics Club');
INSERT INTO campus_societies (id, campus_id, name, category, description, initials) SELECT UUID(), 'ab2a8220-cb6b-11f1-a6f1-8c04ba146d31', 'IDEA Society', 'Entrepreneurship', 'Innovation, Dedication, Evolution & Achievement — promotes entrepreneurial mindsets, startup incubator pitching, and business plan competitions.', 'IDEA' FROM dual WHERE NOT EXISTS (SELECT 1 FROM campus_societies WHERE campus_id='ab2a8220-cb6b-11f1-a6f1-8c04ba146d31' AND name='IDEA Society');
INSERT INTO campus_societies (id, campus_id, name, category, description, initials) SELECT UUID(), 'ab2a8220-cb6b-11f1-a6f1-8c04ba146d31', 'Fine Arts & Photographic Club', 'Fine Arts', 'Develops aesthetic capabilities through painting exhibitions, calligraphy workshops, campus photo walks, and graphic design competitions.', 'FAPC' FROM dual WHERE NOT EXISTS (SELECT 1 FROM campus_societies WHERE campus_id='ab2a8220-cb6b-11f1-a6f1-8c04ba146d31' AND name='Fine Arts & Photographic Club');
INSERT INTO campus_societies (id, campus_id, name, category, description, initials) SELECT UUID(), 'ab2a8220-cb6b-11f1-a6f1-8c04ba146d31', 'Sports Club', 'Sports', 'Organizes intra-campus and inter-varsity championships in cricket, football, basketball, badminton, table tennis, and athletics.', 'SC' FROM dual WHERE NOT EXISTS (SELECT 1 FROM campus_societies WHERE campus_id='ab2a8220-cb6b-11f1-a6f1-8c04ba146d31' AND name='Sports Club');
INSERT INTO campus_societies (id, campus_id, name, category, description, initials) SELECT UUID(), 'ab2a8220-cb6b-11f1-a6f1-8c04ba146d31', 'Environmental Protection Society', 'Social Service', 'Student community focused on plantation drives, climate change awareness, plastic-free campus campaigns, and sustainability projects.', 'EPS' FROM dual WHERE NOT EXISTS (SELECT 1 FROM campus_societies WHERE campus_id='ab2a8220-cb6b-11f1-a6f1-8c04ba146d31' AND name='Environmental Protection Society');
INSERT INTO campus_societies (id, campus_id, name, category, description, initials) SELECT UUID(), 'ab2a8220-cb6b-11f1-a6f1-8c04ba146d31', 'Telecom Society', 'Technical', 'Explores communication networks, 5G wireless systems, and telecommunication hardware through industrial visits and technical exhibitions.', 'TS' FROM dual WHERE NOT EXISTS (SELECT 1 FROM campus_societies WHERE campus_id='ab2a8220-cb6b-11f1-a6f1-8c04ba146d31' AND name='Telecom Society');
INSERT INTO campus_societies (id, campus_id, name, category, description, initials) SELECT UUID(), 'ab2a8220-cb6b-11f1-a6f1-8c04ba146d31', 'COMSATS Literary Society', 'Literary', 'Vibrant student platform bringing together creative writers, essayists, and poets for open mics and literary discussions.', 'CLS' FROM dual WHERE NOT EXISTS (SELECT 1 FROM campus_societies WHERE campus_id='ab2a8220-cb6b-11f1-a6f1-8c04ba146d31' AND name='COMSATS Literary Society');
