INSERT INTO campus_programs (id, campus_id, program_id, fee, duration, details, status, shifts) SELECT UUID(), 'ab2a761b-cb6b-11f1-a6f1-8c04ba146d31', p.id, 'Rs. 135000/semester', '4 Years', '{"eligibility":[{"qualification":"Intermediate","minPct":50.0,"subjects":"","note":"Atleast 50% marks in Intermediate (HSSC) examinations with Mathematics A level or equivalent qualification with Mathematics, certified by IBCC or atleast 50% marks in Intermediate (HSSC) examinations with Pre-Medical or equivalent qualification, certified by IBCC. Valid NTS as per CUI policy."}],"entryTest":"University Test","testBody":"NTS","entryNote":"NTS (NAT)","interviewOn":false,"interviewNote":"","merit":[{"component":"Atleast","weight":50.0},{"component":"certified by IBCC or atleast","weight":50.0}],"fees":[{"head":"Tuition Fee","amount":135000,"frequency":"Per Semester"},{"head":"Admission Fee","amount":22000,"frequency":"One Time"},{"head":"Security Deposit","amount":5000,"frequency":"One Time"}]}', 'published', 'Morning' FROM programs p WHERE p.university_id='f3f5dbc5-cf02-451a-86e1-d468921720f0' AND p.name='Remote Sensing and GIS' AND p.level='Undergraduate' AND NOT EXISTS (SELECT 1 FROM campus_programs WHERE campus_id='ab2a761b-cb6b-11f1-a6f1-8c04ba146d31' AND program_id=p.id);
INSERT INTO campus_programs (id, campus_id, program_id, fee, duration, details, status, shifts) SELECT UUID(), 'ab2a7ee4-cb6b-11f1-a6f1-8c04ba146d31', p.id, 'Rs. 92500/semester', '2 Years', '{"eligibility":[{"qualification":"BS (16 years)","minPct":55.0,"subjects":"","note":"A minimum CGPA of 2.5 out of 4. 0 (in the semester system) or 55% marks (in the annual system) in a sixteen-year degree program in the same or relevant field from an HEC-recognized university/HEI is required. a) NTS/GRE/HAT, General/Subject/Equivalent tests conducted by testing bodies accredited by the HEC, with a passing score of 50% marks. b) In addition, CUI may also conduct/accept subject tests provided the test is not conducted by GRE/NTS/HAT for admission to Master of Science (MS) program with a passing score of 60%, if deemed necessary. Intradisciplinary admission(s) may be considered as per notification."}],"entryTest":"University Test","testBody":"NTS","entryNote":"NTS (GAT-General)","interviewOn":false,"interviewNote":"","merit":[{"component":"in the semester system) or","weight":55.0},{"component":"with a passing score of","weight":50.0},{"component":"CUI may also conduct/accept subject tests provided the test is not conducted by GRE/NTS/HAT for admission to Master of Science (MS) program with a passing score of","weight":60.0}],"fees":[{"head":"Tuition Fee","amount":92500,"frequency":"Per Semester"},{"head":"Admission Fee","amount":27000,"frequency":"One Time"},{"head":"Security Deposit","amount":5000,"frequency":"One Time"}]}', 'published', 'Morning' FROM programs p WHERE p.university_id='f3f5dbc5-cf02-451a-86e1-d468921720f0' AND p.name='Management Sciences' AND p.level='MS' AND NOT EXISTS (SELECT 1 FROM campus_programs WHERE campus_id='ab2a7ee4-cb6b-11f1-a6f1-8c04ba146d31' AND program_id=p.id);
