UPDATE universities SET
  name='COMSATS University Islamabad', normalized_name=LOWER('comsats university islamabad'),
  university_type='Public', hec_rank='1', oric_domain='@comsats.edu.pk',
  focal_person_name='Prof. Dr. Raheel Qamar, T.I.', focal_person_email='admissions@comsats.edu.pk',
  campuses_text='Islamabad Main Campus; Lahore Campus; Abbottabad Campus; Wah Campus; Attock Campus; Sahiwal Campus; Vehari Campus', campus_count='7',
  tagline='Excellence in Higher Education, Innovative Research and Service to Society', hero_subtitle='Chartered public research university by the Federal Government of Pakistan with 7 physical campuses and a Virtual Campus (NOC pending with HEC) nationwide', about_title='About COMSATS University Islamabad',
  about_text='COMSATS University Islamabad (CUI) is a public sector university chartered by the Federal Government of Pakistan in 2018 (originally established as CIIT in 1998). CUI functions under the governance of the Ministry of Science and Technology. The university comprises 7 physical campuses - Islamabad (Main Campus), Lahore, Abbottabad, Wah Cantt, Attock, Sahiwal, and Vehari - plus a Virtual Campus that is currently not operational and is seeking HEC NOC to launch distance learning programs. It hosts 6 faculties, 23 academic departments, 6 research centers, and over 39,000 enrolled students. CUI has consistently ranked among top national universities and leading international institutions according to Times Higher Education (THE) and QS World University Rankings.', mission='The COMSATS University Islamabad, founded in the belief that understanding enriches all people, is dedicated to the search for truth through advancement of learning and extending the frontiers of knowledge; to the sharing of this knowledge through education in an academically diverse range of disciplines and subjects; and to the application of this knowledge to benefit the people of Pakistan, the Muslim Ummah, and the World, at large.', vision='The COMSATS University Islamabad envisions assuming a truly national character for itself in the years to come. It envisions having presence in all provinces of the country. It sees for itself a position among the top five universities in the country; among top 100 universities in the developing countries and top 300, 200, 100 universities in the world respectively in the 5, 10 and 15-years\' time horizon.',
  established_year='1998', website='https://www.comsats.edu.pk', email='admissions@comsats.edu.pk', phone='+92-51-90495032',
  city='Islamabad', address='Park Road, Tarlai Kalan, Islamabad, 45550, Pakistan', logo_url='https://www.comsats.edu.pk/assets/img/COMSATS-logo.png', banner_url='https://www.comsats.edu.pk/assets/img/all-campuses.jpg',
  ranking='1', ranking_label='#1 in Pakistan (THE Impact Rankings 2024)', students='39,100+', employment_rate='88%',
  partner_countries='35+', total_campuses='8', updated_at=NOW()
WHERE id='f3f5dbc5-cf02-451a-86e1-d468921720f0';

